{{!-- Styling parameters: class, titleClass, descriptionClass, contentClass, footerClass --}}
{{#with this as |ghostcnStyles|}}
<div class="ghcn-ui-card{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}default{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}">
  {{#if heading}}<h3 class="ghcn-ui-card__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{heading}}</h3>{{/if}}
  {{#if description}}<p class="ghcn-ui-card__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{description}}</p>{{/if}}
  <div class="ghcn-ui-card__content{{#if ghostcnStyles.contentClass}} {{ghostcnStyles.contentClass}}{{/if}}">{{#> @partial-block}}{{body}}{{/@partial-block}}</div>
  {{#if footer}}<div class="ghcn-ui-card__footer{{#if ghostcnStyles.footerClass}} {{ghostcnStyles.footerClass}}{{/if}}">{{footer}}</div>{{/if}}
</div>
{{/with}}

.ghcn-ui-card { box-sizing: border-box; font-family: inherit; font-size: 16px; line-height: 1.5; color: var(--foreground); }
.ghcn-ui-card, .ghcn-ui-card * { box-sizing: border-box; }
.ghcn-ui-card:where([data-size="sm"]) { font-size: 14px; }
.ghcn-ui-card:where([data-size="lg"]) { font-size: 18px; }
.ghcn-ui-card:focus-visible, .ghcn-ui-card :focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
.ghcn-ui-card { min-width: 0; padding: 1.5em; background: var(--card); color: var(--card-foreground); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: 0 2px 6px #0000000d; overflow-wrap: anywhere; }
.ghcn-ui-card:where([data-variant="secondary"]) { background: var(--secondary); color: var(--secondary-foreground); }
.ghcn-ui-card:where([data-variant="outline"]) { background: transparent; box-shadow: none; }
.ghcn-ui-card__title { font-size: 1.25em; line-height: 1.3; margin: 0 0 .5em; color: inherit; }
.ghcn-ui-card__description { color: inherit; margin: 0 0 1em; }
.ghcn-ui-card__content:empty { display: none; }
.ghcn-ui-card__footer { margin-top: 1em; padding-top: 1em; border-top: 1px solid var(--border); }
